'?></h2><p class="muted">Marca lo que ya viste o leíste. No alojamos contenido de lectura o video.</p><?php foreach($chap as $c):?><div class="chapter"><span>▤ <?=$o['tipo']==='anime'?'Episodio':'Capítulo'?> <?=$c['numero']?> · <?=e($c['titulo'])?></span><form method="post"><?=action('chapter')?><input type="hidden" name="obra" value="<?=$id?>"><input type="hidden" name="capitulo" value="<?=$c['id']?>"><button class="<?=$c['done']?'mint':'outline'?>"><?=$c['done']?'✓ Completado':'Marcar como visto/leído'?></button></form></div><?php endforeach;?></section><section class="panel"><h2>Reseñas</h2><?php foreach($reviews as $r):?><p><b><?=e($r['nombre'])?></b> · <?=str_repeat('★',(int)$r['puntuacion'])?> — <?=e($r['comentario'])?></p><?php endforeach;?><form method="post"><?=action('review')?><input type="hidden" name="obra" value="<?=$id?>"><label>Calificación<select name="rating"><?php for($i=5;$i>=1;$i--):?><option><?=$i?></option><?php endfor;?></select></label><label>Comentario<textarea name="comment" maxlength="2000"></textarea></label><button class="primary">Guardar reseña</button></form></section><?php endif;?>
<?php elseif(in_array($page,['library','favorites','profile'])): $uid=need();$rows=all('SELECT o.*,v.* FROM (SELECT b.usuario_id,b.obra_id,b.estado,b.favorito,  COUNT(c.id) AS total_capitulos,  COUNT(p.capitulo_id) AS completados,  COALESCE(ROUND(100.0*COUNT(p.capitulo_id)/NULLIF(COUNT(c.id),0),1),0) AS porcentaje FROM biblioteca b LEFT JOIN capitulos c ON c.obra_id=b.obra_id LEFT JOIN progreso_capitulos p ON p.usuario_id=b.usuario_id AND p.obra_id=b.obra_id AND p.capitulo_id=c.id GROUP BY b.usuario_id,b.obra_id,b.estado,b.favorito) v JOIN obras o ON o.id=v.obra_id WHERE v.usuario_id=? ORDER BY o.titulo',[$uid]);$filter=$_GET['estado']??'';$total=count($rows);$done=count(array_filter($rows,fn($r)=>$r['estado']==='completado'));$fav=count(array_filter($rows,fn($r)=>$r['favorito']));$units=array_sum(array_column($rows,'completados'));?>
