<?php if($page==='admin'): $nWorks=(int)val('SELECT COUNT(*) FROM obras');$nUsers=(int)val('SELECT COUNT(*) FROM usuarios');$nUnits=(int)val('SELECT COUNT(*) FROM progreso_capitulos');$nChapters=(int)val('SELECT COUNT(*) FROM capitulos');$rating=val('SELECT ROUND(AVG(puntuacion),1) FROM resenas WHERE visible=1');$daily=all('SELECT DATE(completado_en) dia,COUNT(*) n FROM progreso_capitulos WHERE completado_en>=CURRENT_DATE - INTERVAL 6 DAY GROUP BY DATE(completado_en)');$map=array_column($daily,'n','dia');$max=max(array_merge([1],array_values($map)));$series=[];for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$series[]=['label'=>date('d/m',strtotime($d)),'n'=>(int)($map[$d]??0)];}$points=[];foreach($series as $i=>$v){$points[]=(45+$i*65).','.(155-120*$v['n']/$max);} $typeCounts=array_column(all('SELECT tipo, COUNT(*) n FROM obras GROUP BY tipo'),'n','tipo');$a=100*($typeCounts['anime']??0)/max(1,$nWorks);$m=100*($typeCounts['manga']??0)/max(1,$nWorks);?>
<div class="stats admin-stats"><?php foreach([['▤',$nWorks,'Obras'],['▷',$nChapters,'Capítulos / episodios'],['♙',$nUsers,'Usuarios'],['✓',$nUnits,'Unidades completadas'],['☆',$rating??'—','Valoración media']] as $k):?><div><span class="stat-icon"><?=$k[0]?></span><strong><?=e($k[1])?></strong><?=e($k[2])?></div><?php endforeach;?></div>
