<div class="dashboard-charts lower"><section class="panel"><div class="sectionhead"><h2>Obras recientes</h2><a href="<?=url('admin_works')?>">Gestionar →</a></div><?php foreach(all('SELECT * FROM obras ORDER BY id DESC LIMIT 6') as $o):?><div class="recent-row"><img src="<?=e(cover($o))?>" alt=""><div><b><?=e($o['titulo'])?></b><p class="muted"><?=e(ucfirst($o['tipo']))?></p></div><span class="tag mint"><?=e(state($o['estado_publicacion']))?></span></div><?php endforeach;?></section><section class="panel"><h2>Acciones rápidas</h2><div class="quick-actions"><a href="<?=url('admin_works')?>">＋ Registrar obra</a><a href="<?=url('admin_genres')?>">◇ Gestionar géneros</a><a href="<?=url('admin_users')?>">♙ Ver usuarios</a><a href="<?=url('admin_reviews')?>">▧ Moderar comentarios</a></div><h2>Estado de publicación</h2><?php foreach(all('SELECT estado_publicacion,COUNT(*) n FROM obras GROUP BY estado_publicacion') as $v):?><div class="legend-line"><span><?=e(state($v['estado_publicacion']))?></span><b><?=$v['n']?></b></div><progress max="<?=max(1,$nWorks)?>" value="<?=$v['n']?>"></progress><?php endforeach;?></section></div>
